LANDING_HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="SentinelGate is a runtime security gateway for autonomous AI-agent tool calls."><title>SentinelGate — Runtime security for AI agents</title><style>
:root{color-scheme:dark;--bg:#061019;--panel:#0b1822;--line:#1a3443;--text:#eff8fa;--muted:#91a9b5;--mint:#52e2c4;--amber:#ffc875}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 75% -10%,#15374b 0,transparent 38%),var(--bg);font:15px Inter,ui-sans-serif,system-ui;color:var(--text)}a{color:inherit;text-decoration:none}.wrap{max-width:1180px;margin:auto;padding:0 24px}nav{height:78px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:760;font-size:21px;display:flex;gap:12px;align-items:center}.mark{width:26px;height:26px;border:2px solid var(--mint);border-radius:7px;transform:rotate(45deg);box-shadow:0 0 22px #52e2c455}.links{display:flex;align-items:center;gap:25px;color:var(--muted)}.button{display:inline-flex;padding:11px 17px;border-radius:9px;border:1px solid #2c5c67;background:#102832;color:var(--text);font-weight:650}.button.primary{background:var(--mint);color:#052019;border-color:var(--mint)}.hero{padding:100px 0 88px;display:grid;grid-template-columns:1.08fr .92fr;gap:70px;align-items:center}.eyebrow{color:var(--mint);text-transform:uppercase;letter-spacing:.14em;font-size:12px;font-weight:750}.hero h1{font-size:clamp(45px,6.8vw,78px);line-height:.98;letter-spacing:-.065em;margin:20px 0 25px}.hero p{font-size:19px;line-height:1.65;color:#abc0ca;max-width:650px}.actions{display:flex;gap:12px;margin-top:34px;flex-wrap:wrap}.flow{border:1px solid var(--line);background:linear-gradient(145deg,#0e202c,#08141d);border-radius:18px;padding:26px;box-shadow:0 25px 70px #0007}.flow-head{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin-bottom:22px}.step{padding:14px 16px;border:1px solid var(--line);border-radius:10px;background:#0a171f;margin:10px 0;display:flex;justify-content:space-between}.step strong{color:var(--mint)}.arrow{text-align:center;color:#55717d}.blocked{border-color:#74353c;color:#ffc0c6}.proof{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:14px;overflow:hidden;margin:0 0 100px}.proof div{background:#0a171f;padding:24px}.proof b{display:block;font-size:20px;margin-bottom:7px}.proof span{color:var(--muted)}section{padding:85px 0}.section-head{max-width:710px;margin-bottom:42px}.section-head h2{font-size:42px;letter-spacing:-.04em;margin:12px 0}.section-head p{color:var(--muted);line-height:1.65}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{border:1px solid var(--line);border-radius:14px;padding:25px;background:#091720}.card .num{color:var(--mint);font:12px ui-monospace,monospace}.card h3{font-size:18px;margin:18px 0 10px}.card p{color:var(--muted);line-height:1.55;margin:0}.darkband{border-block:1px solid var(--line);background:#07141c}.boundary{display:grid;grid-template-columns:1fr 1fr;gap:35px}.boundary article{padding:30px;border-left:2px solid var(--mint)}.boundary article:last-child{border-color:var(--amber)}.boundary ul{color:var(--muted);line-height:2;padding-left:20px}.cta{margin:90px 0;border:1px solid #275463;background:linear-gradient(120deg,#0d2932,#0b1b27);padding:48px;border-radius:18px;display:flex;justify-content:space-between;align-items:center;gap:30px}.cta h2{font-size:34px;margin:0 0 10px}.cta p{color:var(--muted);margin:0}footer{padding:35px 0 55px;border-top:1px solid var(--line);color:var(--muted);display:flex;justify-content:space-between}.fine{font-size:12px;color:#718995}@media(max-width:850px){.links a:not(.button){display:none}.hero,.boundary{grid-template-columns:1fr}.hero{padding-top:60px}.proof,.cards{grid-template-columns:1fr 1fr}.cta{align-items:flex-start;flex-direction:column}}@media(max-width:520px){.proof,.cards{grid-template-columns:1fr}.hero h1{font-size:48px}}
</style></head><body><div class="wrap"><nav><a class="brand" href="/"><span class="mark"></span>SentinelGate</a><div class="links"><a href="#product">Product</a><a href="#security">Security</a><a href="/docs">API docs</a><a class="button" href="/console">Open console</a></div></nav><main><div class="hero"><div><div class="eyebrow">AI agent runtime security</div><h1>Control what agents can do.</h1><p>SentinelGate sits on the tool-call path, enforcing identity, least privilege, data lineage, taint, approvals and containment before an autonomous agent reaches a real system.</p><div class="actions"><a class="button primary" href="/console">Explore the control plane</a><a class="button" href="/docs">Read the API</a></div><p class="fine">Self-hosted startup preview · Built for design-partner evaluation · No compliance certification claimed</p></div><div class="flow"><div class="flow-head"><span>LIVE DECISION PATH</span><span>ENFORCE</span></div><div class="step"><span>Research agent</span><span>signed identity</span></div><div class="arrow">↓</div><div class="step"><span>Untrusted web result</span><strong>taint attached</strong></div><div class="arrow">↓</div><div class="step"><span>Customer database request</span><span>high risk</span></div><div class="arrow">↓</div><div class="step blocked"><span>Transition denied</span><strong>evidence saved</strong></div></div></div><div class="proof"><div><b>Fail closed</b><span>Unknown tools and invalid identity</span></div><div><b>End-to-end taint</b><span>Across multi-tool traces</span></div><div><b>Exact approvals</b><span>Bound to immutable requests</span></div><div><b>Safe rollout</b><span>Observe, warn, enforce</span></div></div></main></div><div class="darkband" id="product"><div class="wrap"><section><div class="section-head"><div class="eyebrow">One enforcement plane</div><h2>Security controls that follow the action.</h2><p>Agents read, transform and move data between systems. SentinelGate evaluates the full path at the point where intent becomes execution.</p></div><div class="cards"><article class="card"><span class="num">01 / IDENTITY</span><h3>Agent permissions</h3><p>Scoped, expiring identities; tenant isolation; inventory; revocation and bounded containment.</p></article><article class="card"><span class="num">02 / DATA FLOW</span><h3>Provenance and taint</h3><p>Signed lineage, trust and classification propagate so dropping a token cannot launder a trace.</p></article><article class="card"><span class="num">03 / MCP</span><h3>Inline MCP firewall</h3><p>Discover upstream tools, baseline definitions and block poisoned or changed manifests before execution.</p></article><article class="card"><span class="num">04 / POLICY</span><h3>Deterministic decisions</h3><p>Allow, deny or require approval using server-owned rules—never a model granting itself access.</p></article><article class="card"><span class="num">05 / RESPONSE</span><h3>Bounded containment</h3><p>Monitor, restrict, quarantine or revoke an agent with a human-controlled release path.</p></article><article class="card"><span class="num">06 / EVIDENCE</span><h3>Reviewable records</h3><p>Tamper-evident audit events, trace timelines, policy replay and exportable evidence.</p></article></div></section></div></div><div class="wrap" id="security"><section><div class="section-head"><div class="eyebrow">Honest security boundary</div><h2>Designed to be evaluated, not merely believed.</h2></div><div class="boundary"><article><h3>What this build protects</h3><ul><li>Tool calls routed through SentinelGate</li><li>Configured knowledge and GitHub connectors</li><li>Identity, provenance, egress and approval policy</li><li>Configured stateless HTTP MCP upstreams</li></ul></article><article><h3>What it does not claim</h3><ul><li>No protection for paths that bypass it</li><li>No SOC 2, ISO 27001 or regulatory certification</li><li>No autonomous changes to arbitrary infrastructure</li><li>No claim that pattern matching replaces layered controls</li></ul></article></div><div class="cta"><div><h2>Run it against your agent traffic.</h2><p>Start in observe mode, measure decisions, then enforce the paths you trust.</p></div><a class="button primary" href="/console">Open SentinelGate</a></div></section><footer><span>SentinelGate v0.9</span><span>Runtime controls for autonomous agents</span></footer></div></body></html>"""


_CONSOLE_TEMPLATE = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SentinelGate Console</title><style>
:root{color-scheme:dark;--bg:#061019;--side:#08141d;--panel:#0b1923;--line:#1b3444;--text:#edf6f8;--muted:#89a3b1;--mint:#50dfc2;--red:#ff7782;--amber:#ffd073}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:14px Inter,ui-sans-serif,system-ui;color:var(--text)}button,input,textarea{font:inherit}.shell{display:grid;grid-template-columns:245px 1fr;min-height:100vh}.side{border-right:1px solid var(--line);background:var(--side);padding:24px 16px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:760;margin:4px 10px 28px;display:flex;gap:11px;align-items:center}.mark{width:23px;height:23px;border:2px solid var(--mint);border-radius:6px;transform:rotate(45deg)}.navgroup{font-size:10px;color:#5f7d8b;letter-spacing:.13em;margin:22px 11px 8px}.nav a{display:flex;color:var(--muted);text-decoration:none;padding:10px 11px;border-radius:8px;margin:2px 0}.nav a:hover,.nav a.active{color:var(--text);background:#102633}.sidefoot{position:absolute;bottom:22px;left:26px;color:#607b88;font-size:12px}.main{min-width:0}.top{height:73px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 30px;position:sticky;top:0;background:#061019e8;backdrop-filter:blur(12px);z-index:3}.top h1{font-size:19px;margin:0;text-transform:capitalize}.auth{display:flex;gap:7px}.auth input,.field,textarea{border:1px solid var(--line);background:#07131b;color:var(--text);padding:9px 11px;border-radius:8px}.auth input{width:285px}.btn{border:1px solid #285362;background:#102b36;color:var(--text);padding:9px 12px;border-radius:8px;cursor:pointer}.btn:hover{border-color:var(--mint)}.btn.safe{background:#10372e;border-color:#286755}.btn.danger{background:#391a22;border-color:#78333e}.content{padding:30px;max-width:1420px}.hint{color:var(--muted);margin:-5px 0 24px}.error{display:none;background:#3b1720;color:#ffc1c7;padding:11px 14px;border-radius:9px;margin-bottom:16px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:12px}.metric,.panel{border:1px solid var(--line);background:linear-gradient(145deg,#0e1e29,#09151e);border-radius:12px}.metric{padding:18px}.metric b{display:block;font-size:27px}.metric span{color:var(--muted);text-transform:capitalize}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.panel{padding:17px;min-width:0;margin-bottom:14px}.panel.wide{grid-column:1/-1}.panel h2{font-size:15px;margin:0 0 14px;display:flex;justify-content:space-between;align-items:center}.count{color:var(--mint)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px 8px;border-top:1px solid #162c3a;vertical-align:top}th{color:var(--muted);font-size:11px;font-weight:550}.pill{display:inline-block;padding:3px 7px;border-radius:999px;background:#173749;color:#bcefff;font-size:11px}.pill.deny,.pill.blocked,.pill.critical,.pill.high,.pill.quarantine,.pill.restricted,.pill.confidential,.pill.untrusted{background:#3c1c25;color:#ffb1ba}.pill.pending,.pill.review,.pill.medium{background:#3c3217;color:#ffe095}.pill.allow,.pill.trusted,.pill.configured,.pill.passing{background:#133b31;color:#b5f5df}.empty{text-align:center;color:var(--muted);padding:38px}.actions{display:flex;gap:7px;flex-wrap:wrap}.link{color:var(--mint);cursor:pointer;text-decoration:underline}.mono{font:12px ui-monospace,monospace}.toolbar{display:flex;gap:8px;margin-bottom:13px;flex-wrap:wrap}.toolbar .field{min-width:260px}.editor{width:100%;min-height:340px;font:12px ui-monospace,monospace;resize:vertical}.callout{padding:14px;border-left:3px solid var(--mint);background:#0b2029;color:#a9c1cb;margin-bottom:15px}.callout.warn{border-color:var(--amber)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#061019;padding:14px;border:1px solid var(--line);border-radius:8px}dialog{width:min(900px,92vw);max-height:82vh;overflow:auto;background:#0a1720;color:var(--text);border:1px solid var(--line);border-radius:13px;padding:20px}dialog::backdrop{background:#000b}@media(max-width:880px){.shell{grid-template-columns:1fr}.side{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}.nav{display:flex;overflow:auto}.navgroup,.sidefoot{display:none}.top{position:static;padding:15px;gap:15px;height:auto;align-items:flex-start;flex-direction:column}.auth{width:100%}.auth input{width:auto;flex:1}.content{padding:18px}.grid{grid-template-columns:1fr}}
</style></head><body><div class="shell"><aside class="side"><a href="/" class="brand" style="color:inherit;text-decoration:none"><span class="mark"></span>SentinelGate</a><div class="nav"><div class="navgroup">OPERATE</div><a data-page="overview" href="/console">Overview</a><a data-page="traces" href="/console/traces">Data flows</a><a data-page="approvals" href="/console/approvals">Approvals</a><a data-page="agents" href="/console/agents">Agents</a><a data-page="incidents" href="/console/incidents">Incidents</a><div class="navgroup">CONFIGURE</div><a data-page="connectors" href="/console/connectors">Connectors</a><a data-page="mcp-security" href="/console/mcp-security">MCP security</a><a data-page="policy" href="/console/policy">Policy lab</a><div class="navgroup">EVIDENCE</div><a data-page="audit" href="/console/audit">Audit log</a><a data-page="reports" href="/console/reports">Reports</a></div><div class="sidefoot">v0.9 · design-partner release</div></aside><main class="main"><header class="top"><div><h1 id="title"></h1><span id="mode" class="pill">offline</span></div><div class="auth"><input id="token" type="password" autocomplete="off" placeholder="Raw admin token — no Bearer prefix"><button class="btn" onclick="connect()">Connect</button></div></header><div class="content"><div id="error" class="error"></div><p id="hint" class="hint"></p><div id="view"></div></div></main></div><dialog id="detail"><div class="actions" style="justify-content:space-between"><strong id="detailTitle">Details</strong><button class="btn" onclick="detail.close()">Close</button></div><pre id="detailBody"></pre></dialog><script>
const section=__SECTION__;let cache={};const descriptions={overview:'Current posture and recent enforcement activity.',traces:'Follow trust, classification and taint across multi-tool execution.',approvals:'Inspect the exact frozen request before approving one-time execution.',agents:'Manage agent identities, scopes and emergency containment.',incidents:'Correlated high-risk policy events by agent and trace.',connectors:'Review configured execution boundaries and repository allowlists.','mcp-security':'Inspect MCP tool descriptions and schemas before trusting a server.',policy:'Replay current or proposed policy against encrypted historical decisions.',audit:'Verify and inspect the tamper-evident event chain.',reports:'Export operational security evidence for pilot and control reviews.'};document.querySelector(`[data-page="${section}"]`)?.classList.add('active');title.textContent=section.replaceAll('-',' ');hint.textContent=descriptions[section];token.value=sessionStorage.getItem('sentinelgate_admin_token')||'';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pill=v=>`<span class="pill ${esc(v)}">${esc(v)}</span>`;const when=v=>new Date(v).toLocaleString();function table(headers,rows){return rows.length?`<div style="overflow:auto"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:'<div class="empty">No records yet</div>'}async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{Authorization:'Bearer '+token.value,'Content-Type':'application/json',...(opts.headers||{})}});if(!r.ok)throw new Error(`${r.status} ${await r.text()}`);return r.json()}function show(name,value){detailTitle.textContent=name;detailBody.textContent=JSON.stringify(value,null,2);detail.showModal()}function fail(e){error.textContent=e.message;error.style.display='block'}async function connect(){sessionStorage.setItem('sentinelgate_admin_token',token.value);error.style.display='none';try{const h=await fetch('/health').then(r=>r.json());mode.textContent=`v${h.version} · ${h.enforcement_mode}`;mode.className=`pill ${h.audit_chain_valid?'passing':'blocked'}`;await load()}catch(e){fail(e)}}async function load(){const fn={'overview':overview,'traces':traces,'approvals':approvals,'agents':agents,'incidents':incidents,'connectors':connectors,'mcp-security':mcpSecurity,'policy':policy,'audit':audit,'reports':reports}[section];return fn()}
async function overview(){const [m,a,i,t]=await Promise.all([api('/v1/metrics'),api('/v1/approvals?status=pending'),api('/v1/incidents'),api('/v1/activity?limit=12')]);view.innerHTML=`<section class="metrics">${Object.entries(m).map(([k,v])=>`<div class="metric"><b>${v}</b><span>${esc(k.replaceAll('_',' '))}</span></div>`).join('')}</section><div class="grid"><section class="panel"><h2>Pending approvals <span class="count">${a.length}</span></h2>${table(['Agent','Tool','Expires'],a.slice(0,5).map(x=>`<tr><td>${esc(x.agent_id)}</td><td>${esc(x.request.tool_name)}</td><td>${when(x.expires_at)}</td></tr>`))}</section><section class="panel"><h2>Open incidents <span class="count">${i.length}</span></h2>${table(['Severity','Agent','Summary'],i.slice(0,5).map(x=>`<tr><td>${pill(x.severity)}</td><td>${esc(x.agent_id)}</td><td>${esc(x.summary)}</td></tr>`))}</section><section class="panel wide"><h2>Recent activity</h2>${activityTable(t)}</section></div>`}function activityTable(t){return table(['Time','Agent','Trace','Tool','Category','Decision'],t.map(x=>`<tr><td>${when(x.created_at)}</td><td>${esc(x.agent_id)}</td><td class="mono">${esc(x.trace_id.slice(0,14))}</td><td>${esc(x.tool_name)}</td><td>${pill(x.category)}</td><td>${pill(x.decision)}</td></tr>`))}
async function traces(){const data=await api('/v1/traces?limit=200');cache.traces=data;view.innerHTML=`<div class="toolbar"><input class="field" id="filter" placeholder="Filter agent, trace or taint" oninput="filterTraces()"></div><section class="panel"><div id="traceTable">${traceRows(data)}</div></section>`}function traceRows(data){return table(['Updated','Agent','Trace','Classification','Trust','Taint','Nodes'],data.map(x=>`<tr><td>${when(x.last_seen)}</td><td>${esc(x.agent_id)}</td><td><span class="link mono" onclick="openTrace('${esc(x.trace_id)}')">${esc(x.trace_id)}</span></td><td>${pill(x.classification)}</td><td>${pill(x.trust)}</td><td>${x.labels.length?x.labels.map(pill).join(' '):'<span class="hint">clean</span>'}</td><td>${x.node_count}</td></tr>`))}function filterTraces(){const q=filter.value.toLowerCase();traceTable.innerHTML=traceRows(cache.traces.filter(x=>JSON.stringify(x).toLowerCase().includes(q)))}async function openTrace(id){show('Trace lineage',await api(`/v1/traces/${encodeURIComponent(id)}/lineage`))}
async function approvals(){const data=await api('/v1/approvals?status=pending');cache.approvals=Object.fromEntries(data.map(x=>[x.id,x]));view.innerHTML=`<section class="panel">${table(['Agent','Tool','Exact payload','Expires','Decision'],data.map(x=>`<tr><td>${esc(x.agent_id)}</td><td>${esc(x.request.tool_name)}</td><td><span class="link" onclick="show('Approval request',cache.approvals['${x.id}'])">Inspect</span></td><td>${when(x.expires_at)}</td><td><div class="actions"><button class="btn safe" onclick="decide('${x.id}','approve')">Approve & execute</button><button class="btn danger" onclick="decide('${x.id}','reject')">Reject</button></div></td></tr>`))}</section>`}async function decide(id,action){const note=prompt(`${action} reason:`)||`${action}d in console`;await api(`/v1/approvals/${id}/${action}`,{method:'POST',body:JSON.stringify({reviewer:'console-operator',note})});if(action==='approve')await api(`/v1/approvals/${id}/execute`,{method:'POST'});await approvals()}
async function agents(){const [data,c]=await Promise.all([api('/v1/agents'),api('/v1/containments')]);view.innerHTML=`<section class="panel"><h2>Agent identities</h2>${table(['Agent','Owner','Scopes','Tokens','Status',''],data.map(x=>`<tr><td>${esc(x.tenant_id)} / ${esc(x.agent_id)}</td><td>${esc(x.owner)}</td><td>${x.scopes.map(pill).join(' ')}</td><td>${x.active_tokens}</td><td>${pill(x.status)}</td><td><button class="btn danger" onclick="contain('${esc(x.tenant_id)}','${esc(x.agent_id)}')">Quarantine</button></td></tr>`))}</section><section class="panel"><h2>Active containments</h2>${table(['Mode','Agent','Reason','Expires',''],c.map(x=>`<tr><td>${pill(x.mode)}</td><td>${esc(x.agent_id)}</td><td>${esc(x.reason)}</td><td>${when(x.expires_at)}</td><td><button class="btn" onclick="releaseContainment('${x.id}')">Release</button></td></tr>`))}</section>`}async function contain(t,a){const reason=prompt(`Reason for quarantining ${a}:`);if(!reason)return;await api(`/v1/agents/${encodeURIComponent(t)}/${encodeURIComponent(a)}/contain`,{method:'POST',body:JSON.stringify({mode:'quarantine',reviewer:'console-operator',reason,duration_seconds:900})});agents()}async function releaseContainment(id){await api(`/v1/containments/${id}/release`,{method:'POST',body:JSON.stringify({reviewer:'console-operator',note:'Released in console'})});agents()}
async function incidents(){const data=await api('/v1/incidents');view.innerHTML=`<section class="panel">${table(['Severity','Agent','Trace','Investigation','Events','Status'],data.map(x=>`<tr><td>${pill(x.severity)}</td><td>${esc(x.agent_id)}</td><td class="mono">${esc(x.trace_id)}</td><td>${esc(x.summary)}</td><td>${x.event_count}</td><td>${pill(x.status)}</td></tr>`))}</section>`}async function connectors(){const data=await api('/v1/connectors');view.innerHTML=`<div class="callout">Configured is not the same as reachable. GitHub can be verified live without exposing credentials.</div><div class="actions"><button class="btn primary" onclick="verifyGitHub()">Verify GitHub connection</button></div><section class="panel">${table(['Connector','Status','Mode','Boundary'],data.map(x=>`<tr><td>${esc(x.name)}</td><td>${pill(x.status)}</td><td>${esc(x.mode)}</td><td>${(x.repository_allowlist||x.servers||[]).map(pill).join(' ')||'Local configured root'}</td></tr>`))}</section>`}async function verifyGitHub(){try{show('GitHub verification',await api('/v1/connectors/github/verify',{method:'POST',body:'{}'}))}catch(e){fail(e)}}
function mcpSecurity(){const example={tools:[{name:'search_docs',description:'Search approved documentation.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false}}],accept_baseline:false};view.innerHTML=`<div class="callout warn">Paste a server's <span class="mono">tools/list</span> result. Clean first observations become baselines; later silent changes are blocked.</div><section class="panel"><div class="toolbar"><input id="serverId" class="field" value="example-server" aria-label="MCP server ID"><button class="btn safe" onclick="inspectMcp()">Inspect manifest</button></div><textarea id="manifest" class="editor">${esc(JSON.stringify(example,null,2))}</textarea><div id="mcpResult"></div></section>`}async function inspectMcp(){try{const result=await api(`/v1/mcp/servers/${encodeURIComponent(serverId.value)}/inspect`,{method:'POST',body:manifest.value});mcpResult.innerHTML=`<h2>Result ${pill(result.safe?'trusted':'blocked')}</h2>`+table(['Tool','Digest','Changed','Status','Findings'],result.tools.map(x=>`<tr><td>${esc(x.tool_name)}</td><td class="mono">${esc(x.digest)}</td><td>${x.changed}</td><td>${pill(x.status)}</td><td>${x.findings.map(f=>pill(f.code)).join(' ')||'None'}</td></tr>`))}catch(e){fail(e)}}
async function policy(){const current=await api('/v1/policy');view.innerHTML=`<div class="callout">Editing here does not activate policy. Replay compares a proposal with historical decisions; deployment remains explicit.</div><section class="panel"><div class="toolbar"><button class="btn safe" onclick="replayProposed()">Replay proposed policy</button><button class="btn" onclick="replayCurrent()">Replay current policy</button></div><textarea id="policyEditor" class="editor">${esc(JSON.stringify(current,null,2))}</textarea><div id="policyResult"></div></section>`}async function replayProposed(){const result=await api('/v1/policy/replay',{method:'POST',body:JSON.stringify({policy:JSON.parse(policyEditor.value),limit:500})});policyResult.innerHTML=`<pre>${esc(JSON.stringify(result,null,2))}</pre>`}async function replayCurrent(){const result=await api('/v1/policy/replay',{method:'POST',body:JSON.stringify({limit:500})});policyResult.innerHTML=`<pre>${esc(JSON.stringify(result,null,2))}</pre>`}
async function audit(){const data=await api('/v1/audit?limit=200');cache.audit=Object.fromEntries(data.map(x=>[x.id,x]));view.innerHTML=`<div class="callout">Audit chain status is shown in the header. Payloads are redacted before persistence.</div><section class="panel">${table(['Time','Type','Event','Payload'],data.map(x=>`<tr><td>${when(x.created_at)}</td><td>${pill(x.event_type)}</td><td class="mono">${esc(x.id.slice(0,12))}</td><td><span class="link" onclick="show('Audit event',cache.audit['${x.id}'])">Inspect</span></td></tr>`))}</section>`}
async function reports(){const r=await api('/v1/reports/security');cache.report=r;view.innerHTML=`<div class="callout warn">This operational evidence summary is not a compliance certification.</div><div class="toolbar"><button class="btn safe" onclick="downloadReport()">Download JSON evidence</button><button class="btn" onclick="downloadAuditCsv()">Download audit CSV</button></div><section class="metrics">${Object.entries(r.policy_decisions.verdicts).map(([k,v])=>`<div class="metric"><b>${v}</b><span>${esc(k)} decisions</span></div>`).join('')}</section><section class="panel"><h2>Control evidence</h2>${table(['Control','Evidence','Status'],r.control_evidence.map(x=>`<tr><td>${esc(x.control)}</td><td>${x.evidence.map(pill).join(' ')}</td><td>${pill(x.status)}</td></tr>`))}</section><section class="panel"><h2>Top reason codes</h2>${table(['Reason','Count'],r.policy_decisions.top_reason_codes.map(x=>`<tr><td class="mono">${esc(x.reason)}</td><td>${x.count}</td></tr>`))}</section>`}function downloadReport(){const blob=new Blob([JSON.stringify(cache.report,null,2)],{type:'application/json'});saveBlob(blob,'sentinelgate-security-evidence.json')}async function downloadAuditCsv(){const r=await fetch('/v1/reports/audit.csv',{headers:{Authorization:'Bearer '+token.value}});if(!r.ok)throw new Error(await r.text());saveBlob(await r.blob(),'sentinelgate-audit.csv')}function saveBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}if(token.value)connect();
</script></body></html>"""


def console_page(section: str) -> str:
    return _CONSOLE_TEMPLATE.replace("__SECTION__", json.dumps(section))
